'use strict';
const CACHE='socio-studio-cloud-members-v8';
const FILES=['./','./index.html','./manifest.webmanifest','./icon-192.png','./icon-512.png'];
self.addEventListener('install',event=>{event.waitUntil((async()=>{const cache=await caches.open(CACHE);for(const file of FILES){try{const response=await fetch(file,{credentials:'same-origin',cache:'reload'});if(response.ok&&!response.redirected)await cache.put(file,response)}catch{}}await self.skipWaiting()})())});
self.addEventListener('activate',event=>{event.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith('socio-studio-')&&key!==CACHE)await caches.delete(key);await self.clients.claim()})())});
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin)return;const allowed=new Set(FILES.map(file=>new URL(file,self.registration.scope).pathname));if(!allowed.has(url.pathname))return;event.respondWith((async()=>{try{const response=await fetch(event.request);if(response.ok&&!response.redirected){const cache=await caches.open(CACHE);await cache.put(event.request,response.clone())}return response}catch{const cached=await caches.match(event.request);if(cached)return cached;if(event.request.mode==='navigate'){const index=await caches.match(new URL('./index.html',self.registration.scope));if(index)return index}return new Response('Sin conexión. Abre la aplicación al menos una vez con conexión.',{status:503,headers:{'Content-Type':'text/plain;charset=utf-8'}})}})())});
